<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { useRoute, useRouter } from 'vue-router'
import { api } from '../api/client'
import type { Material } from '../types'
interface Option { id:number; name:string; full_path?:string }
const route=useRoute();const router=useRouter();const saving=ref(false);const editing=Boolean(route.params.id)
const categories=ref<Option[]>([]);const locations=ref<Option[]>([]);const suppliers=ref<Option[]>([])
const requestedCategory=Number(route.query.category_id)||null
const requestedLocation=Number(route.query.location_id)||null
const form=reactive({code:'',name:'',category_id:requestedCategory as number|null,location_id:requestedLocation as number|null,supplier_id:null as number|null,mpn:'',specification:'',package:'',footprint:'',manufacturer:'',supplier_part_number:'',unit:'pcs',unit_price:0,safety_stock:0,target_stock:0,barcode:'',lifecycle_status:'active',rohs_status:'unknown',datasheet_url:'',tags:[] as string[],attributes:{} as Record<string,unknown>,notes:'',is_active:true})
onMounted(async()=>{const [c,l,s]=await Promise.all([api.get<Option[]>('/categories'),api.get<Option[]>('/locations'),api.get<Option[]>('/suppliers')]);categories.value=c.data;locations.value=l.data;suppliers.value=s.data;if(editing){const {data}=await api.get<Material>(`/materials/${route.params.id}`);for(const key of Object.keys(form) as (keyof typeof form)[]){if(key in data)(form[key] as unknown)=(data[key as keyof Material] as unknown)}}})
async function submit(){if(!form.code||!form.name)return; saving.value=true;try{if(editing){const {code,...payload}=form;void code;await api.put(`/materials/${route.params.id}`,payload)}else await api.post('/materials',form);ElMessage.success(editing?'物料已更新':'物料已创建');router.push(route.query.return_to==='categories'?'/categories':'/materials')}finally{saving.value=false}}
</script>
<template><div class="page narrow"><div class="page-header"><div><h1 class="page-title">{{editing?'编辑物料':'新增物料'}}</h1><div class="page-subtitle">库存数量只能通过库存操作修改，此处维护基础资料</div></div><el-button @click="$router.back()">返回</el-button></div><el-form :model="form" label-position="top"><el-card class="card section"><template #header><b>基础信息</b></template><div class="form-grid"><el-form-item label="内部物料编码" required><el-input v-model="form.code" :disabled="editing" placeholder="例如 MAT-IC-0001"/></el-form-item><el-form-item label="物料名称" required><el-input v-model="form.name"/></el-form-item><el-form-item label="MPN / 型号"><el-input v-model="form.mpn"/></el-form-item><el-form-item label="厂家"><el-input v-model="form.manufacturer"/></el-form-item><el-form-item label="分类"><el-select v-model="form.category_id" clearable filterable><el-option v-for="x in categories" :key="x.id" :label="x.name" :value="x.id"/></el-select></el-form-item><el-form-item label="默认库位"><el-select v-model="form.location_id" clearable filterable><el-option v-for="x in locations" :key="x.id" :label="x.full_path||x.name" :value="x.id"/></el-select></el-form-item><el-form-item label="默认供应商"><el-select v-model="form.supplier_id" clearable filterable><el-option v-for="x in suppliers" :key="x.id" :label="x.name" :value="x.id"/></el-select></el-form-item><el-form-item label="供应商料号"><el-input v-model="form.supplier_part_number"/></el-form-item></div></el-card><el-card class="card section"><template #header><b>工程参数</b></template><div class="form-grid"><el-form-item label="规格值"><el-input v-model="form.specification" placeholder="10kΩ / 100nF"/></el-form-item><el-form-item label="封装"><el-input v-model="form.package" placeholder="0603 / SOIC-8"/></el-form-item><el-form-item label="PCB Footprint"><el-input v-model="form.footprint"/></el-form-item><el-form-item label="单位"><el-input v-model="form.unit"/></el-form-item><el-form-item label="条形码"><el-input v-model="form.barcode"/></el-form-item><el-form-item label="RoHS"><el-select v-model="form.rohs_status"><el-option label="未知" value="unknown"/><el-option label="符合" value="compliant"/><el-option label="不符合" value="noncompliant"/></el-select></el-form-item><el-form-item label="生命周期"><el-select v-model="form.lifecycle_status"><el-option label="在产" value="active"/><el-option label="不推荐新设计" value="nrnd"/><el-option label="停产" value="obsolete"/></el-select></el-form-item><el-form-item label="标签"><el-select v-model="form.tags" multiple filterable allow-create default-first-option/></el-form-item></div></el-card><el-card class="card section"><template #header><b>库存阈值与采购</b></template><div class="form-grid"><el-form-item label="安全库存"><el-input-number v-model="form.safety_stock" :min="0" :precision="4"/></el-form-item><el-form-item label="目标库存"><el-input-number v-model="form.target_stock" :min="0" :precision="4"/></el-form-item><el-form-item label="单价"><el-input-number v-model="form.unit_price" :min="0" :precision="4"/></el-form-item><el-form-item label="数据手册链接"><el-input v-model="form.datasheet_url"/></el-form-item></div><el-form-item label="备注"><el-input v-model="form.notes" type="textarea" :rows="3"/></el-form-item></el-card><div class="actions"><el-button @click="$router.back()">取消</el-button><el-button type="primary" :loading="saving" :disabled="!form.code||!form.name" @click="submit">保存物料</el-button></div></el-form></div></template>
<style scoped>.narrow{max-width:1160px}.section{margin-bottom:16px}.form-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:0 18px}.form-grid :deep(.el-select),.form-grid :deep(.el-input-number){width:100%}.actions{display:flex;justify-content:flex-end;gap:8px;padding:8px 0 30px}@media(max-width:900px){.form-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.form-grid{grid-template-columns:1fr}}</style>
